use super::*;
fn fixture()->(PathBuf,Value){let root=std::env::temp_dir().join(format!("starlane-archive-output-{}",random_operation().unwrap()));std::fs::create_dir(&root).unwrap();std::fs::create_dir(root.join("vault")).unwrap();let binding=json!({"context":{"session":"original"},"revision":"rev","root":root.join("vault")});(root,binding)}
fn stage(root:&Path,binding:&Value)->Staged{let selected=Selected::admit(root.join("out.zip"),binding.clone()).unwrap();let mut stage=Staged::create(selected,sha(b"manifest")).unwrap();stage.file.write_all(b"exact original archive bytes").unwrap();stage.seal().unwrap();stage}
#[test]fn no_clobber_and_exact_readback(){let(root,b)=fixture();let s=stage(&root,&b);let op=s.journal.operation.clone();s.publish(||Ok(()),||Ok(b.clone()),|_|Ok(())).unwrap();assert_eq!(std::fs::read(root.join("out.zip")).unwrap(),b"exact original archive bytes");assert_eq!(inspect(&root,&op,&b).unwrap()["state"],"published_verified");assert!(Selected::admit(root.join("out.zip"),b).is_err());std::fs::remove_dir_all(root).unwrap();}
#[test]fn interruption_phases_restart_readonly(){for phase in["sealed","journal","link","fsync"]{let(root,b)=fixture();let s=stage(&root,&b);let op=s.journal.operation.clone();assert!(s.publish(||Ok(()),||Ok(b.clone()),|p|if p==phase{Err("interrupted".into())}else{Ok(())}).is_err());let r=inspect(&root,&op,&b).unwrap();assert_eq!(r["state"],if phase=="link"||phase=="fsync"{"published_verified"}else if phase=="journal"{"unresolved_output_absent"}else{"sealed_unpublished"});assert_eq!(r["automatic_retry"],false);std::fs::remove_dir_all(root).unwrap();}}
#[test]fn source_context_and_late_target_refuse(){for mode in["source","context","target"]{let(root,b)=fixture();let s=stage(&root,&b);let op=s.journal.operation.clone();if mode=="target"{std::fs::write(root.join("out.zip"),b"foreign").unwrap();}assert!(s.publish(||if mode=="source"{Err("stale source".into())}else{Ok(())},||if mode=="context"{Ok(json!({}))}else{Ok(b.clone())},|_|Ok(())).is_err());if mode=="target"{assert_eq!(std::fs::read(root.join("out.zip")).unwrap(),b"foreign");}else{assert!(!root.join("out.zip").exists());}assert!(inspect(&root,&op,&json!({})).is_err());std::fs::remove_dir_all(root).unwrap();}}
#[test]fn equal_content_stage_replacement_refuses(){let(root,b)=fixture();let s=stage(&root,&b);let op=s.journal.operation.clone();let path=s.dir.path.join("archive.zip");std::fs::rename(&path,path.with_extension("held")).unwrap();std::fs::write(&path,b"exact original archive bytes").unwrap();assert!(s.publish(||Ok(()),||Ok(b.clone()),|_|Ok(())).is_err());assert!(inspect(&root,&op,&b).is_err());assert!(!root.join("out.zip").exists());std::fs::remove_dir_all(root).unwrap();}
#[test]fn changed_parent_and_foreign_output_conflict(){let(root,b)=fixture();let s=stage(&root,&b);let op=s.journal.operation.clone();assert!(s.publish(||Ok(()),||Ok(b.clone()),|p|if p=="journal"{Err("stop".into())}else{Ok(())}).is_err());std::fs::write(root.join("out.zip"),b"exact original archive bytes").unwrap();assert_eq!(inspect(&root,&op,&b).unwrap()["state"],"conflict");let moved=root.with_extension("moved");std::fs::rename(&root,&moved).unwrap();std::fs::create_dir(&root).unwrap();assert!(inspect(&root,&op,&b).is_err());std::fs::remove_dir_all(root).unwrap();std::fs::remove_dir_all(moved).unwrap();}
#[test]fn source_containment_and_unsafe_targets_refuse(){let(root,b)=fixture();assert!(Selected::admit(root.join("vault/out.zip"),b.clone()).is_err());use std::os::unix::fs::symlink;symlink(root.join("missing"),root.join("out.zip")).unwrap();assert!(Selected::admit(root.join("out.zip"),b).is_err());std::fs::remove_dir_all(root).unwrap();}

#[test]fn acknowledged_output_removed_never_becomes_unpublished_authority(){let(root,b)=fixture();let s=stage(&root,&b);let op=s.journal.operation.clone();s.publish(||Ok(()),||Ok(b.clone()),|_|Ok(())).unwrap();std::fs::remove_file(root.join("out.zip")).unwrap();let r=inspect(&root,&op,&b).unwrap();assert_eq!(r["state"],"published_output_missing");assert_eq!(r["automatic_retry"],false);std::fs::remove_dir_all(root).unwrap();}

fn prior_observation(root:&Path,binding:&Value)->(String,Value,Vec<u8>){let original=stage(root,binding);let operation=original.journal.operation.clone();assert!(original.publish(||Ok(()),||Ok(binding.clone()),|p|if p=="journal"{Err("original unknown ack".into())}else{Ok(())}).is_err());let report=recovery::pending(root,binding).unwrap()["operations"][0].clone();let raw=std::fs::read(root.join(format!(".starlane-archive-{operation}/journal.json"))).unwrap();(operation,report,raw)}
#[test]fn current_reexport_owns_new_inode_and_operation_preserves_original(){let(root,b)=fixture();let(original,report,raw)=prior_observation(&root,&b);let prior=recovery::SealedOriginal::capture(&root,&b,&report).unwrap();let selected=Selected::admit(root.join("new-selected.zip"),b.clone()).unwrap().with_prior(prior).unwrap();let ack=selected.report();assert_eq!(ack["reexport_provenance"]["original_operation"],original);assert_eq!(ack["reexport_provenance"]["new_operation_required"],true);assert_eq!(ack["reexport_provenance"]["original_creator_authority"],false);assert_eq!(ack["reexport_provenance"]["publication_retry"],false);let mut new=Staged::create(selected,sha(b"manifest")).unwrap();assert_ne!(new.journal.operation,original);let newoperation=new.journal.operation.clone();new.file.write_all(b"exact original archive bytes").unwrap();new.seal().unwrap();let result=new.publish(||Ok(()),||Ok(b.clone()),|_|Ok(())).unwrap();assert_eq!(result["operation"],newoperation);assert_eq!(std::fs::read(root.join("new-selected.zip")).unwrap(),b"exact original archive bytes");assert!(!root.join("out.zip").exists());assert_eq!(std::fs::read(root.join(format!(".starlane-archive-{original}/journal.json"))).unwrap(),raw);let old=std::fs::metadata(root.join(format!(".starlane-archive-{original}/archive.zip"))).unwrap();let published=std::fs::metadata(root.join("new-selected.zip")).unwrap();assert_ne!(old.ino(),published.ino());assert_eq!(old.nlink(),1);let provenance:Value=serde_json::from_slice(&std::fs::read(root.join(format!(".starlane-archive-{newoperation}/reexport-provenance.json"))).unwrap()).unwrap();assert_eq!(provenance["original_creator_authority"],false);assert_eq!(provenance["publication_retry"],false);std::fs::remove_dir_all(root).unwrap();}
#[test]fn changed_current_bytes_cannot_publish_historical_observation(){let(root,b)=fixture();let(_,report,_)=prior_observation(&root,&b);let prior=recovery::SealedOriginal::capture(&root,&b,&report).unwrap();let selected=Selected::admit(root.join("new-selected.zip"),b.clone()).unwrap().with_prior(prior).unwrap();let mut new=Staged::create(selected,sha(b"manifest")).unwrap();new.file.write_all(b"foreign newer archive bytes").unwrap();assert!(new.seal().is_err());assert!(!root.join("new-selected.zip").exists());std::fs::remove_dir_all(root).unwrap();}
#[test]fn original_observation_change_and_published_absence_never_grant_old_authority(){for mode in ["report","stage","output","context"]{let(root,b)=fixture();let(operation,mut report,_)=prior_observation(&root,&b);if mode=="report"{report["stage"]["sha256"]=json!("fabricated");assert!(recovery::SealedOriginal::capture(&root,&b,&report).is_err());}else if mode=="context"{let mut wrong=b.clone();wrong["revision"]=json!("other");assert!(recovery::SealedOriginal::capture(&root,&wrong,&report).is_err());}else{let prior=recovery::SealedOriginal::capture(&root,&b,&report).unwrap();if mode=="stage"{let path=root.join(format!(".starlane-archive-{operation}/archive.zip"));std::fs::rename(&path,path.with_extension("held")).unwrap();std::fs::write(path,b"exact original archive bytes").unwrap();}else{std::fs::write(root.join("out.zip"),b"foreign destination").unwrap();}assert!(prior.fence().is_err());}std::fs::remove_dir_all(root).unwrap();}}

#[test]fn late_equal_length_same_inode_corruption_never_acknowledges_publication(){let(root,b)=fixture();let s=stage(&root,&b);let op=s.journal.operation.clone();let original=b"exact original archive bytes";let altered=vec![b'x';original.len()];let result=s.publish(||Ok(()),||Ok(b.clone()),|phase|{if phase=="fsync"{std::fs::write(root.join("out.zip"),&altered).unwrap();}Ok(())});assert!(result.unwrap_err().contains("complete-byte readback differs"));let raw:Journal=serde_json::from_slice(&std::fs::read(root.join(format!(".starlane-archive-{op}/journal.json"))).unwrap()).unwrap();assert_eq!(raw.state,"publication_unknown");assert_eq!(std::fs::read(root.join("out.zip")).unwrap(),altered);assert!(inspect(&root,&op,&b).is_err());assert!(root.join(format!(".starlane-archive-{op}/archive.zip")).exists());std::fs::remove_dir_all(root).unwrap();}
#[test]#[ignore="actual100MiB owned-stage postlink checksum/readback control; no GUI choice"]
fn bounded100mib_postlink_fullreadback(){let(root,b)=fixture();let selected=Selected::admit(root.join("out.zip"),b.clone()).unwrap();let mut s=Staged::create(selected,sha(b"manifest")).unwrap();let buffer=[7u8;65536];for _ in 0..1600{s.file.write_all(&buffer).unwrap();}s.seal().unwrap();let report=s.publish(||Ok(()),||Ok(b.clone()),|_|Ok(())).unwrap();assert_eq!(report["byte_length"],104857600);let mut f=std::fs::File::open(root.join("out.zip")).unwrap();let mut chunks=[0u8;65536];let mut bytes=0;let mut h=Sha256::new();loop{let n=f.read(&mut chunks).unwrap();if n==0{break}assert!(chunks[..n].iter().all(|v|*v==7));bytes+=n;h.update(&chunks[..n]);}assert_eq!(bytes,104857600);assert_eq!(report["sha256"],format!("{:x}",h.finalize()));std::fs::remove_dir_all(root).unwrap();}
